"""Tensor-parallel linear layers (Megatron-style).

Weights follow the torch.nn.Linear convention: shape (out_features, in_features),
and y = x @ W^T + b.
"""
import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _all_reduce(t):
    if _world_size() == 1:
        return t
    t = t.contiguous()
    dist.all_reduce(t, op=dist.ReduceOp.SUM)
    return t


def _all_gather_last_dim(t):
    ws = _world_size()
    if ws == 1:
        return t
    t = t.contiguous()
    parts = [torch.empty_like(t) for _ in range(ws)]
    dist.all_gather(parts, t)
    return torch.cat(parts, dim=-1).contiguous()


def _split_last_dim(t):
    ws = _world_size()
    if ws == 1:
        return t
    return torch.chunk(t, ws, dim=-1)[_rank()].contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce gradient."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad.clone())


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take this rank's slice of the last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _all_gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take this rank's slice."""

    @staticmethod
    def forward(ctx, x):
        return _all_gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


class ColumnParallelLinear(torch.nn.Module):
    """Y = X A + b with A split along its columns (output features).

    Each rank holds weight of shape (out_features / world_size, in_features)
    and bias of shape (out_features / world_size,). Outputs are all-gathered
    along the last dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        if out_features % self.world_size != 0:
            raise ValueError("out_features must be divisible by world_size")
        self.out_features_per_partition = out_features // self.world_size

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight must have shape {(out_features, in_features)}, "
            f"got {tuple(master_weight.shape)}"
        )
        start = self.rank * self.out_features_per_partition
        end = start + self.out_features_per_partition
        shard = master_weight.detach()[start:end, :].clone().contiguous()
        self.weight = torch.nn.Parameter(shard)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(self.out_features_per_partition,
                            dtype=shard.dtype, device=shard.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        local = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(local)


class RowParallelLinear(torch.nn.Module):
    """Y = X A + b with A split along its rows (input features).

    Each rank holds weight of shape (out_features, in_features / world_size).
    Partial outputs are all-reduced (summed); the full bias is then added on
    every rank.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        if in_features % self.world_size != 0:
            raise ValueError("in_features must be divisible by world_size")
        self.in_features_per_partition = in_features // self.world_size

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight must have shape {(out_features, in_features)}, "
            f"got {tuple(master_weight.shape)}"
        )
        start = self.rank * self.in_features_per_partition
        end = start + self.in_features_per_partition
        shard = master_weight.detach()[:, start:end].clone().contiguous()
        self.weight = torch.nn.Parameter(shard)

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features, dtype=shard.dtype, device=shard.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already-split input.
        if self.world_size > 1 and x.shape[-1] == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        elif x.shape[-1] != self.in_features_per_partition:
            raise ValueError(
                f"Expected last dim {self.in_features} or "
                f"{self.in_features_per_partition}, got {x.shape[-1]}"
            )
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
